results.content:
1	#!/usr/bin/env bash
2	# GRPO | vision | vLLM rollout | Megatron training | NVIDIA GPUs
3	
4	set -xeuo pipefail
5	
6	export CUDA_DEVICE_MAX_CONNECTIONS=1
7	
8	# ---- user-adjustable ----
9	MODEL_PATH=${MODEL_PATH:-Qwen/Qwen3-VL-8B-Instruct}
10	NNODES=${NNODES:-1}
11	NGPUS_PER_NODE=${NGPUS_PER_NODE:-8}
12	
13	train_batch_size=${TRAIN_BATCH_SIZE:-512}
14	ppo_mini_batch_size=${PPO_MINI_BATCH_SIZE:-128}
15	max_prompt_length=${MAX_PROMPT_LENGTH:-1024}
16	max_response_length=${MAX_RESPONSE_LENGTH:-2048}
17	ppo_max_token_len_per_gpu=${PPO_MAX_TOKEN_LEN_PER_GPU:-24576}
18	
19	actor_lr=${ACTOR_LR:-1e-6}
20	kl_loss_coef=${KL_LOSS_COEF:-0.01}
21	entropy_coeff=${ENTROPY_COEFF:-0}
22	
23	actor_tp=${ACTOR_TP:-2}
24	actor_pp=${ACTOR_PP:-2}
25	
26	rollout_tp=${ROLLOUT_TP:-2}
27	rollout_gpu_mem_util=${ROLLOUT_GPU_MEM_UTIL:-0.6}
28	rollout_n=${ROLLOUT_N:-5}
29	
30	total_epochs=${TOTAL_EPOCHS:-15}
31	save_freq=${SAVE_FREQ:-20}
32	test_freq=${TEST_FREQ:-5}
33	
34	project_name=${PROJECT_NAME:-verl_grpo_geo3k}
35	experiment_name=${EXPERIMENT_NAME:-qwen3_vl_8b_vllm_megatron}
36	# ---- end user-adjustable ----
37	########################### parameter arrays ###########################
38	
39	DATA=(
40	    algorithm.adv_estimator=grpo
41	    algorithm.use_kl_in_reward=False
42	    data.train_files=$HOME/data/geo3k/train.parquet
43	    data.val_files=$HOME/data/geo3k/test.parquet
44	    data.image_key=images
45	    data.train_batch_size=${train_batch_size}
46	    data.max_prompt_length=${max_prompt_length}
47	    data.max_response_length=${max_response_length}
48	    data.filter_overlong_prompts=True
49	    data.truncation='error'
50	)
51	
52	MODEL=(
53	    actor_rollout_ref.model.path="$MODEL_PATH"
54	    actor_rollout_ref.model.use_remove_padding=True
55	    actor_rollout_ref.model.use_fused_kernels=True
56	)
57	
58	ACTOR=(
59	    actor_rollout_ref.actor.optim.lr=${actor_lr}
60	    actor_rollout_ref.actor.ppo_mini_batch_size=${ppo_mini_batch_size}
61	    actor_rollout_ref.actor.use_dynamic_bsz=True
62	    actor_rollout_ref.actor.ppo_max_token_len_per_gpu=${ppo_max_token_len_per_gpu}
63	    actor_rollout_ref.actor.use_kl_loss=True
64	    actor_rollout_ref.actor.kl_loss_coef=${kl_loss_coef}
65	    actor_rollout_ref.actor.kl_loss_type=low_var_kl
66	    actor_rollout_ref.actor.entropy_coeff=${entropy_coeff}
67	    actor_rollout_ref.actor.megatron.tensor_model_parallel_size=${actor_tp}
68	    actor_rollout_ref.actor.megatron.pipeline_model_parallel_size=${actor_pp}
69	    actor_rollout_ref.actor.megatron.use_mbridge=True
70	)
71	
72	ROLLOUT=(
73	    actor_rollout_ref.rollout.name=vllm
74	    actor_rollout_ref.rollout.tensor_model_parallel_size=${rollout_tp}
75	    actor_rollout_ref.rollout.gpu_memory_utilization=${rollout_gpu_mem_util}
76	    actor_rollout_ref.rollout.n=${rollout_n}
77	    actor_rollout_ref.rollout.log_prob_use_dynamic_bsz=True
78	    actor_rollout_ref.rollout.log_prob_max_token_len_per_gpu=${ppo_max_token_len_per_gpu}
79	)
80	
81	REF=(
82	    actor_rollout_ref.ref.log_prob_use_dynamic_bsz=True
83	    actor_rollout_ref.ref.log_prob_max_token_len_per_gpu=${ppo_max_token_len_per_gpu}
84	    actor_rollout_ref.ref.megatron.tensor_model_parallel_size=${actor_tp}
85	    actor_rollout_ref.ref.megatron.pipeline_model_parallel_size=${actor_pp}
86	    actor_rollout_ref.ref.megatron.use_mbridge=True
87	)
88	
89	TRAINER=(
90	    trainer.balance_batch=True
91	    trainer.logger='["console","wandb"]'
92	    trainer.project_name=${project_name}
93	    trainer.experiment_name=${experiment_name}
94	    trainer.n_gpus_per_node=${NGPUS_PER_NODE}
95	    trainer.nnodes=${NNODES}
96	    trainer.save_freq=${save_freq}
97	    trainer.test_freq=${test_freq}
98	    trainer.total_epochs=${total_epochs}
99	)
100	
101	EXTRA=(
102	    model_engine=megatron
103	)
104	
105	########################### launch ###########################
106	python3 -m verl.trainer.main_ppo \
107	    "${DATA[@]}" \
108	    "${MODEL[@]}" \
109	    "${ACTOR[@]}" \
110	    "${ROLLOUT[@]}" \
111	    "${REF[@]}" \
112	    "${TRAINER[@]}" \
113	    "${EXTRA[@]}" \
